1	// sc4sap:program-to-spec — Template-clone xlsx renderer.
2	//
3	// Strategy (양식 보존 / format-preserving):
4	//   1. Read asset/template_base.xlsx (canonical reference workbook —
5	//      English-source ZMMRTEST003 spec with all styles, borders, fonts, column
6	//      widths, row heights, drawings, images intact).
7	//   2. Re-zip every entry byte-for-byte EXCEPT xl/sharedStrings.xml.
8	//   3. For xl/sharedStrings.xml, replace each <t>…</t> content using the
9	//      user-supplied translation map TR { "English key": "한국어 값" }.
10	//   4. Write the resulting xlsx to outPath.
11	//
12	// Why this exists:
13	//   The previous workflow built xlsx geometry from JSON (SHEETS_DATA + custom
14	//   styles), which silently drifted from the agreed reference format. By
15	//   cloning the template and only swapping text payload, the output is GUARANTEED
16	//   to match the reference layout exactly — styles, borders, image anchors,
17	//   row heights, column widths all preserved.
18	//
19	// Slot semantics (must be honoured by the TR map producer — sap-writer):
20	//   · Sheet 1 (Program Overview): 17 Field/Value rows
21	//   · Sheet 2 (Data Model):       4 table rows (slots: VBAK → MARA-style, VBAP →
22	//                                 MARC-style, KNA1 → MAKT-style, MAKT → 4th) +
23	//                                 CDS Views / BAPIs / BAdIs trailer rows
24	//   · Sheet 3 (Inputs & Screens): 5 parameter slots (S_VKORG..S_VBELN) + 5
25	//                                 warning rows. Repurpose unused slots with
26	//                                 "— (해당 없음)" placeholders to keep row count.
27	//   · Sheet 4 (Processing Logic): 12 step slots. Use "—" for unused.
28	//   · Sheet 5 (Output):           10 ALV column slots. Use "—" for unused.
29	//   · Sheet 6 (Authorizations):   5 rows.
30	//   · Sheet 7 (Exceptions):       3 rows.
31	//
32	// SAP standard identifiers (table names, field names, parameter names) that
33	// happen to match the source spec (ZMMRTEST003 / VBAK / VBELN / S_VKORG …)
34	// MUST be present as TR keys to swap them for the target program's identifiers.
35	// Identifiers absent from TR remain in the cloned file unchanged.
36	
37	import { readFileSync, writeFileSync, existsSync } from 'node:fs';
38	import { deflateRawSync, inflateRawSync } from 'node:zlib';
39	import { dirname, resolve } from 'node:path';
40	import { fileURLToPath } from 'node:url';
41	
42	const __dirname = dirname(fileURLToPath(import.meta.url));
43	
44	// =============================================================
45	// ZIP read/write — minimal, zero-dep
46	// =============================================================
47	const CRC_TABLE = (() => {
48	  const t = new Uint32Array(256);
49	  for (let n = 0; n < 256; n++) {
50	    let c = n;
51	    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
52	    t[n] = c >>> 0;
53	  }
54	  return t;
55	})();
56	function crc32(buf) {
57	  let c = 0xffffffff;
58	  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
59	  return (c ^ 0xffffffff) >>> 0;
60	}
61	function u16(n) { const b = Buffer.alloc(2); b.writeUInt16LE(n, 0); return b; }
62	function u32(n) { const b = Buffer.alloc(4); b.writeUInt32LE(n >>> 0, 0); return b; }
63	
64	function unzipEntries(buf) {
65	  let eocd = -1;
66	  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
67	    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
68	  }
69	  if (eocd < 0) throw new Error('template-clone: EOCD not found in template');
70	  const cdEntries = buf.readUInt16LE(eocd + 10);
71	  const cdOffset = buf.readUInt32LE(eocd + 16);
72	  const entries = [];
73	  let p = cdOffset;
74	  for (let i = 0; i < cdEntries; i++) {
75	    const method = buf.readUInt16LE(p + 10);
76	    const compSize = buf.readUInt32LE(p + 20);
77	    const nameLen = buf.readUInt16LE(p + 28);
78	    const extraLen = buf.readUInt16LE(p + 30);
79	    const commentLen = buf.readUInt16LE(p + 32);
80	    const lfhOffset = buf.readUInt32LE(p + 42);
81	    const name = buf.slice(p + 46, p + 46 + nameLen).toString('utf8');
82	    const lNameLen = buf.readUInt16LE(lfhOffset + 26);
83	    const lExtraLen = buf.readUInt16LE(lfhOffset + 28);
84	    const dataStart = lfhOffset + 30 + lNameLen + lExtraLen;
85	    const compData = buf.slice(dataStart, dataStart + compSize);
86	    const data = method === 0 ? compData : inflateRawSync(compData);
87	    entries.push({ name, data });
88	    p += 46 + nameLen + extraLen + commentLen;
89	  }
90	  return entries;
91	}
92	
93	function zipFiles(entries) {
94	  const locals = [], centrals = [];
95	  let offset = 0;
96	  for (const e of entries) {
97	    const nameBuf = Buffer.from(e.name, 'utf8');
98	    const raw = e.data;
99	    const compressed = deflateRawSync(raw, { level: 9 });
100	    const useDeflate = compressed.length < raw.length;
101	    const body = useDeflate ? compressed : raw;
102	    const method = useDeflate ? 8 : 0;
103	    const crc = crc32(raw);
104	    const local = Buffer.concat([
105	      u32(0x04034b50), u16(20), u16(0x0800), u16(method),
106	      u16(0), u16(0), u32(crc), u32(body.length), u32(raw.length),
107	      u16(nameBuf.length), u16(0), nameBuf,
108	    ]);
109	    locals.push(local, body);
110	    const central = Buffer.concat([
111	      u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(method),
112	      u16(0), u16(0), u32(crc), u32(body.length), u32(raw.length),
113	      u16(nameBuf.length), u16(0), u16(0), u16(0), u16(0),
114	      u32(0), u32(offset), nameBuf,
115	    ]);
116	    centrals.push(central);
117	    offset += local.length + body.length;
118	  }
119	  const centralSize = centrals.reduce((s, p) => s + p.length, 0);
120	  const eocd = Buffer.concat([
121	    u32(0x06054b50), u16(0), u16(0),
122	    u16(entries.length), u16(entries.length),
123	    u32(centralSize), u32(offset), u16(0),
124	  ]);
125	  return Buffer.concat([...locals, ...centrals, eocd]);
126	}
127	
128	// =============================================================
129	// sharedStrings.xml translation
130	// =============================================================
131	function translateSharedStrings(xml, tr, { warnUntranslated = true } = {}) {
132	  const missing = [];
133	  const out = xml.replace(/<t([^>]*)>([\s\S]*?)<\/t>/g, (m, attrs, body) => {
134	    const decoded = body
135	      .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
136	      .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
137	      .replace(/&amp;/g, '&');
138	    const translated = tr[decoded];
139	    if (translated == null) {
140	      // English-looking strings that lack a mapping are likely bugs in the TR map.
141	      // Pure-ASCII single tokens (table names, field codes) are intentionally
142	      // unmapped when the target program shares the identifier.
143	      if (warnUntranslated && /[A-Za-z]/.test(decoded) && decoded.length > 1) {
144	        missing.push(decoded.slice(0, 80));
145	      }
146	      return m;
147	    }
148	    const enc = translated
149	      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
150	      .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
151	    const needsSpace = /^\s|\s$|\n/.test(translated);
152	    const newAttrs = needsSpace && !/xml:space/.test(attrs)
153	      ? ' xml:space="preserve"' + attrs : attrs;
154	    return `<t${newAttrs}>${enc}</t>`;
155	  });
156	  return { xml: out, missing };
157	}
158	
159	// =============================================================
160	// Public API
161	// =============================================================
162	export function cloneTemplate({ outPath, tr, templatePath, verbose = true }) {
163	  // Default: <repo-root>/asset/template_base.xlsx (two levels up from scripts/spec/).
164	  const tplPath = templatePath
165	    || resolve(__dirname, '..', '..', 'asset', 'template_base.xlsx');
166	  if (!existsSync(tplPath)) {
167	    throw new Error(`template-clone: template not found at ${tplPath}`);
168	  }
169	  const src = readFileSync(tplPath);
170	  const entries = unzipEntries(src);
171	  let foundSS = false;
172	  let missing = [];
173	  for (const e of entries) {
174	    if (e.name === 'xl/sharedStrings.xml') {
175	      foundSS = true;
176	      const result = translateSharedStrings(e.data.toString('utf8'), tr);
177	      e.data = Buffer.from(result.xml, 'utf8');
178	      missing = result.missing;
179	    }
180	  }
181	  if (!foundSS) throw new Error('template-clone: xl/sharedStrings.xml missing from template');
182	  const out = zipFiles(entries);
183	  writeFileSync(outPath, out);
184	  if (verbose) {
185	    console.log(`template-clone: wrote ${outPath} (${out.length} bytes)`);
186	    if (missing.length > 0) {
187	      console.log(`template-clone: ${missing.length} English string(s) had no TR mapping:`);
188	      for (const s of missing.slice(0, 20)) console.log(`  · ${JSON.stringify(s)}`);
189	      if (missing.length > 20) console.log(`  · … (${missing.length - 20} more)`);
190	    }
191	  }
192	  return { outPath, bytes: out.length, missing };
193	}
194	
195	// CLI usage:  node template-clone.mjs <tr-json-path> <out-xlsx-path>
196	// Run unconditionally when invoked as the entrypoint script (process.argv[1]
197	// equals this file). On Windows, fileURLToPath round-trip handles drive-letter
198	// + backslash mismatches that broke the older `file://` comparison.
199	const thisFile = fileURLToPath(import.meta.url);
200	if (process.argv[1] && resolve(process.argv[1]) === thisFile) {
201	  const [trPath, outPath] = process.argv.slice(2);
202	  if (!trPath || !outPath) {
203	    console.error('Usage: node template-clone.mjs <tr-json-path> <out-xlsx-path>');
204	    process.exit(2);
205	  }
206	  const tr = JSON.parse(readFileSync(trPath, 'utf8'));
207	  cloneTemplate({ outPath, tr });
208	}
