458	  const TERM_H_MIN = 38;
459	  const DIAMOND_H_MIN = 60;
460	  const LINE_H = 18;          // px per text line
461	  const PAD_TOP = 48;
462	  const PAD_BOT = 28;
463	  const ARROW_H = 30;
464	  const LEFT = (width - BOX_W) / 2;
465	  const BLUE = '#0A4F8C';
466	  const YELLOW = '#FFFDE7';
467	  const GRAY_FILL = '#EFEFEF';
468	
469	  let y = PAD_TOP;
470	  const parts = [];
471	
472	  // Heading row
473	  parts.push(`<text x="${width / 2}" y="${y - 16}" text-anchor="middle" font-size="15" font-weight="700" fill="${BLUE}">${xml(heading)}</text>`);
474	
475	  items.forEach((raw, i) => {
476	    const txt = String(raw ?? '');
477	    const isDecision = /^\?\s*/.test(txt);
478	    const isTerminal = /^!\s*/.test(txt);
479	    const label = isDecision ? txt.replace(/^\?\s*/, '')
480	                 : isTerminal ? txt.replace(/^!\s*/, '')
481	                 : txt;
482	    const kind = isDecision ? 'decision' : isTerminal ? 'terminal' : 'process';
483	    const lines = labelLinesAndHeight(label, BOX_W, kind);
484	    const lineCount = lines.length;
485	    const textBlockH = lineCount * LINE_H;
486	
487	    if (isDecision) {
488	      const boxH = Math.max(DIAMOND_H_MIN, textBlockH + 28);
489	      const cx = width / 2, cy = y + boxH / 2;
490	      const dx = BOX_W / 2, dy = boxH / 2;
491	      parts.push(`<polygon points="${cx},${cy - dy} ${cx + dx},${cy} ${cx},${cy + dy} ${cx - dx},${cy}" fill="${YELLOW}" stroke="${BLUE}" stroke-width="1.6"/>`);
492	      const startY = cy - ((lineCount - 1) * LINE_H) / 2 + 5;
493	      lines.forEach((line, li) => {
494	        parts.push(`<text x="${cx}" y="${startY + li * LINE_H}" text-anchor="middle" font-size="12" fill="#222">${xml(line)}</text>`);
495	      });
496	      y += boxH;
497	    } else if (isTerminal) {
498	      const boxH = Math.max(TERM_H_MIN, textBlockH + 16);
499	      parts.push(`<rect x="${LEFT}" y="${y}" width="${BOX_W}" height="${boxH}" rx="${boxH / 2}" fill="${GRAY_FILL}" stroke="${BLUE}" stroke-width="1.6"/>`);
500	      const startY = y + boxH / 2 - ((lineCount - 1) * LINE_H) / 2 + 5;
501	      lines.forEach((line, li) => {
502	        parts.push(`<text x="${width / 2}" y="${startY + li * LINE_H}" text-anchor="middle" font-size="12" font-weight="700" fill="${BLUE}">${xml(line)}</text>`);
503	      });
504	      y += boxH;
505	    } else {
506	      const boxH = Math.max(BOX_H_MIN, textBlockH + 16);
507	      parts.push(`<rect x="${LEFT}" y="${y}" width="${BOX_W}" height="${boxH}" fill="#FFFFFF" stroke="${BLUE}" stroke-width="1.6"/>`);
508	      const startY = y + boxH / 2 - ((lineCount - 1) * LINE_H) / 2 + 5;
509	      lines.forEach((line, li) => {
510	        parts.push(`<text x="${width / 2}" y="${startY + li * LINE_H}" text-anchor="middle" font-size="12" fill="#222">${xml(line)}</text>`);
511	      });
512	      y += boxH;
513	    }
514	
515	    // Arrow between items
