  const { totalW } = pfHorizontalLayout(items);
  const totalH = PF_H_PAD_TOP + PF_H_BOX_H + PF_H_PAD_BOT;
  return { width: Math.round(totalW * RENDER_SCALE), height: Math.round(totalH * RENDER_SCALE) };
}

