// sc4sap:program-to-spec — Image swap helper for cloned spec xlsx files.
//
// PURPOSE
//   Replace the two program-agnostic mockup PNGs embedded in the spec
//   workbook (xl/media/image1.png + xl/media/image2.png) with program-
//   specific PNGs. The xl/drawings/drawing3.xml + rels stay untouched,
//   so the new images inherit the original anchors and extents:
//     · image2.png  → anchor C4,  ext 8572500×2667000 EMU (Selection)
//     · image1.png  → anchor C19, ext 9715500×1752600 EMU (ALV grid)
//
// WHY A SEPARATE HELPER (and not part of template-clone)
//   template_base.xlsx is the permanent reference. Once cloned, the
//   downstream caller may or may not have program-specific PNGs. Keeping
//   the swap step out of the clone path means the default program-to-spec
//   workflow stays drift-free (cf. project_program_to_spec_image_embed_
//   followup memory). The swap is opt-in: trigger keywords only.
//
// API
//   swapImages({ xlsxPath, selectionPng?, alvPng? })
//     xlsxPath      absolute path to a cloned spec xlsx (will be rewritten in place)
//     selectionPng  Buffer | string (file path) → replaces xl/media/image2.png (top, C4)
//     alvPng        Buffer | string (file path) → replaces xl/media/image1.png (bottom, C19)
//   Either input may be omitted; omitted slots keep the template image.
//   Returns { xlsxPath, swapped: { selection: bool, alv: bool }, bytes }.
//
// CLI (zero-dep)
//   node image-swap.mjs <xlsx> --selection <path> --alv <path>
//   node image-swap.mjs <xlsx> <selection.png> <alv.png>   # positional, use "-" to skip
//
// SAFETY
//   · PNG signature is verified (89 50 4E 47 0D 0A 1A 0A); non-PNG input is
//     rejected before the xlsx is rewritten, so a bad swap never corrupts
//     the workbook.
//   · template_base.xlsx is never touched by this helper. Callers are
//     expected to pass an already-cloned xlsx.
//   · drawing3.xml and its rels are explicitly preserved byte-for-byte.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { resolve, dirname } from 'node:path';
import { unzipEntries, zipFiles } from './xlsx-zip.mjs';

const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function loadPng(input, label) {
  if (input == null) return null;
  let buf;
  if (Buffer.isBuffer(input)) {
    buf = input;
  } else if (typeof input === 'string') {
    if (!existsSync(input)) {
      throw new Error(`image-swap: ${label} PNG not found at ${input}`);
    }
    buf = readFileSync(input);
  } else {
    throw new Error(`image-swap: ${label} must be Buffer or file path, got ${typeof input}`);
  }
  if (buf.length < 8 || !PNG_SIG.equals(buf.slice(0, 8))) {
    throw new Error(`image-swap: ${label} does not have a valid PNG signature`);
  }
  return buf;
}

export function swapImages({ xlsxPath, selectionPng = null, alvPng = null, verbose = true }) {
  if (!xlsxPath) throw new Error('image-swap: xlsxPath is required');
  if (!existsSync(xlsxPath)) throw new Error(`image-swap: xlsx not found at ${xlsxPath}`);
  const selBuf = loadPng(selectionPng, 'selectionPng');
  const alvBuf = loadPng(alvPng, 'alvPng');
  if (!selBuf && !alvBuf) {
    if (verbose) console.log('image-swap: nothing to swap (both inputs null) — file untouched');
    return { xlsxPath, swapped: { selection: false, alv: false }, bytes: 0 };
  }

  const src = readFileSync(xlsxPath);
  const entries = unzipEntries(src);
  let sawSel = false, sawAlv = false;
  for (const e of entries) {
    if (selBuf && e.name === 'xl/media/image2.png') {
      e.data = selBuf;
      sawSel = true;
    } else if (alvBuf && e.name === 'xl/media/image1.png') {
      e.data = alvBuf;
      sawAlv = true;
    }
  }
  if (selBuf && !sawSel) {
    throw new Error('image-swap: xl/media/image2.png slot not found — wrong template?');
  }
  if (alvBuf && !sawAlv) {
    throw new Error('image-swap: xl/media/image1.png slot not found — wrong template?');
  }
  const out = zipFiles(entries);
  writeFileSync(xlsxPath, out);
  if (verbose) {
    const tag = [];
    if (sawSel) tag.push(`selection→image2.png (${selBuf.length} B)`);
    if (sawAlv) tag.push(`alv→image1.png (${alvBuf.length} B)`);
    console.log(`image-swap: ${xlsxPath} updated — ${tag.join(', ')} | total ${out.length} B`);
  }
  return { xlsxPath, swapped: { selection: sawSel, alv: sawAlv }, bytes: out.length };
}

// ──────────────────────────────────────────────────────────────
