    if (sawSel) tag.push(`selection→image2.png (${sel.buf.length} B)`);
    if (sawAlv) tag.push(`alv→image1.png (${alv.buf.length} B)`);
    if (pf)     tag.push(`processFlow→image3.png (${pf.buf.length} B, ${pf.width}×${pf.height} px)`);
