280	export function renderAlvLayoutSVG({ columns = [], sampleRows = [], maxRows = 3, lang = 'ko' } = {}) {
281	  const L = legendFor(lang);
282	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
283	  const totalW = columns.reduce((s, c) => s + (c.width || 100), 0) + 20;
284	  const w = Math.max(900, Math.min(totalW, 1600));
285	  const rowH = 24;
286	  const headerH = 22;
287	  // Spec-driven legend feature detection — only include items that apply.
288	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
289	  const hasHotspot  = columns.some(c => c.hotspot);
290	  const hasEditable = columns.some(c => c.editable);
291	  const hasLegend   = hasStatus || hasHotspot || hasEditable;
292	  const legendPad   = hasLegend ? 80 : 30;
293	  const h = 10 + headerH + rows.length * rowH + legendPad;
294	
295	  let x = 10;
296	  const colX = columns.map(c => { const left = x; x += (c.width || 100); return left; });
297	  const gridRight = x;
298	
299	  const headerCells = columns.map((c, i) => {
300	    const cx = colX[i] + (c.width || 100) / 2;
301	    return `<text x="${cx}" y="${10 + headerH - 7}" text-anchor="middle" font-weight="700" fill="#0A4F8C">${xml(c.header || c.name)}</text>`;
302	  }).join('');
303	
304	  const sepLines = colX.slice(1).map(lx =>
305	    `<line x1="${lx}" y1="10" x2="${lx}" y2="${10 + headerH + rows.length * rowH}" stroke="#C8D4E2"/>`).join('');
306	
307	  const dataRows = rows.map((r, rIdx) => {
308	    const y = 10 + headerH + rIdx * rowH;
309	    const bg = r._locked ? '#F0F5FA' : (rIdx % 2 === 1 ? '#F5F9FC' : '#FFF');
310	    const bandBg = rIdx % 2 === 1 || r._locked
311	      ? `<rect x="10" y="${y}" width="${gridRight - 10}" height="${rowH}" fill="${bg}"/>` : '';
312	    const cells = columns.map((c, ci) => {
313	      const cx = colX[ci] + (c.width || 100) / 2;
314	      const leftX = colX[ci] + 8, rightX = colX[ci] + (c.width || 100) - 8;
315	      const cy = y + rowH - 8;
316	      const val = r[c.name];
317	      const statusFill = { '●': '#D4A017', '○': '#C0392B', '◉': '#1E8449' };
318	      if (c.name === '_status' || c.editable) {
319	        if (c.editable) {
320	          const editBg = r._locked ? '#E5E5E5' : '#FFF6C8';
321	          const editStroke = r._locked ? '#999' : '#A67F25';
322	          return `<rect x="${colX[ci] + 2}" y="${y + 3}" width="${(c.width || 100) - 4}" height="${rowH - 6}" fill="${editBg}" stroke="${editStroke}"/>`
323	            + (val !== undefined ? `<text x="${rightX}" y="${cy}" text-anchor="end" font-family="monospace" fill="${r._locked ? '#888' : '#000'}">${xml(val)}</text>` : '');
324	        }
325	      }
326	      if (val === undefined || val === null || val === '') return '';
327	      const strVal = String(val);
328	      if (c.name === '_status') {
329	        return `<text x="${cx}" y="${cy}" text-anchor="middle" fill="${statusFill[strVal] || '#555'}" font-weight="700">${xml(strVal)}</text>`;
330	      }
331	      if (c.hotspot) {
332	        return `<text x="${cx}" y="${cy}" text-anchor="middle" font-family="monospace" fill="#1F5AA0" text-decoration="underline">${xml(strVal)}</text>`;
333	      }
334	      const anchor = c.align === 'end' ? 'end' : (c.align === 'left' ? 'start' : 'middle');
335	      const tx = anchor === 'end' ? rightX : anchor === 'start' ? leftX : cx;
336	      const fam = /^[\d.,\-]+$/.test(strVal) ? 'monospace' : 'Arial,sans-serif';
337	      return `<text x="${tx}" y="${cy}" text-anchor="${anchor}" font-family="${fam}">${xml(strVal)}</text>`;
338	    }).join('');
339	    return bandBg + cells;
340	  }).join('');
341	
342	  const legendY = 10 + headerH + rows.length * rowH + 30;
343	
344	  const legendParts = [];
345	  if (hasStatus) {
346	    legendParts.push(
347	      `<tspan fill="#1E8449" font-weight="700">◉</tspan> ${xml(L.status_done)}`,
348	      `<tspan fill="#D4A017" font-weight="700">●</tspan> ${xml(L.status_partial)}`,
349	      `<tspan fill="#C0392B" font-weight="700">○</tspan> ${xml(L.status_open)}`,
350	    );
351	  }
352	  if (hasHotspot)  legendParts.push(`<tspan fill="#1F5AA0" text-decoration="underline">${xml(L.hotspot_text)}</tspan> ${xml(L.hotspot_label)}`);
353	  if (hasEditable) legendParts.push(`<tspan>${xml(L.editable_cell)}</tspan> ${xml(L.editable_label)}`);
354	  const legendSvg = hasLegend
355	    ? `<text x="10" y="${legendY}" font-size="11" fill="#555">${legendParts.join(' · ')}</text>`
356	    : '';
357	
358	  return `<?xml version="1.0" encoding="UTF-8"?>
359	<svg xmlns="http://www.w3.org/2000/svg" width="${Math.round(w * RENDER_SCALE)}" height="${Math.round(h * RENDER_SCALE)}" viewBox="0 0 ${w} ${h}" font-family="Arial,sans-serif" font-size="12">
360	<rect width="${w}" height="${h}" fill="#FFF"/>
361	<rect x="10" y="10" width="${gridRight - 10}" height="${headerH}" fill="#D0DEED" stroke="#3E7DB3"/>
362	${headerCells}
363	${dataRows}
364	<rect x="10" y="10" width="${gridRight - 10}" height="${headerH + rows.length * rowH}" fill="none" stroke="#C8D4E2"/>
365	${sepLines}
366	${legendSvg}
367	</svg>`;
368	}
369	
370	/**
371	 * ALV layout dimensions — mirrors the formulas in renderAlvLayoutSVG so
372	 * callers (renderScreenImages) can size the headless browser viewport
373	 * without duplicating the feature-detection logic.
374	 */
375	export function alvLayoutMetrics({ columns = [], sampleRows = [], maxRows = 3 } = {}) {
376	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
377	  const totalW = columns.reduce((s, c) => s + (c.width || 100), 0) + 20;
378	  const w = Math.max(900, Math.min(totalW, 1600));
379	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
380	  const hasHotspot  = columns.some(c => c.hotspot);
381	  const hasEditable = columns.some(c => c.editable);
382	  const legendPad   = (hasStatus || hasHotspot || hasEditable) ? 80 : 30;
383	  const h = 10 + 22 + rows.length * 24 + legendPad;
384	  return { width: Math.round(w * RENDER_SCALE), height: Math.round(h * RENDER_SCALE) };
385	}
