    const y = 10 + headerH + rIdx * rowH;
    const bg = r._locked ? '#F0F5FA' : (rIdx % 2 === 1 ? '#F5F9FC' : '#FFF');
    const bandBg = rIdx % 2 === 1 || r._locked
      ? `<rect x="10" y="${y}" width="${gridRight - 10}" height="${rowH}" fill="${bg}"/>` : '';
