cd "C:/Users/user/Desktop/SC4 Project/superclaude-for-sap" && node -e "
const tr = JSON.parse(require('fs').readFileSync('.sc4sap/specs/_tr/ZMMRTEST004-20260524.tr.json','utf8'));
const ss = require('child_process').execSync('unzip -p asset/template_base.xlsx xl/sharedStrings.xml','{stdio:[\"pipe\",\"pipe\",\"ignore\"]}').toString();
const inlineStrings = [...ss.matchAll(/<t[^>]*>([^<]+)</g)].map(m => m[1].replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'\"'));
const missing = inlineStrings.filter(s => !(s in tr));
console.log('Template unique strings:', new Set(inlineStrings).size);
console.log('Missing from TR:', missing.length);
if (missing.length) console.log('  ', missing.slice(0,10).join('\n   '));
"
